    *{box-sizing:border-box}body{margin:0;min-width:320px;background:var(--bg);color:var(--ink);line-height:1.45}button,input,select{font:inherit}button{border:0;cursor:pointer}button:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid var(--focus);outline-offset:2px}
    .shell{width:min(960px,100%);margin:0 auto;padding:24px 20px 56px}.topbar{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:22px}.topbar-actions{display:flex;align-items:center;gap:10px;flex:none}.topbar-context{color:var(--muted);font-size:12px}.brand{display:flex;align-items:center;gap:11px;min-width:0}.brand-mark{display:grid;place-items:center;width:36px;height:36px;border-radius:10px;background:var(--accent);color:#fff;font-weight:800}.brand-copy{min-width:0}.brand-title{font-size:20px;font-weight:750;line-height:1.2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.brand-subtitle{margin-top:3px;color:var(--muted);font-size:12px}
