    .notice{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:0 0 12px;padding:11px 12px;border:1px solid var(--line);border-radius:8px;background:var(--subtle);font-size:13px}.notice.error{border-color:var(--danger);color:var(--danger)}.notice .button{flex:none}.empty,.loading{padding:30px 18px;text-align:center;color:var(--muted)}.empty-title{color:var(--ink);font-weight:700}.empty-detail{margin-top:5px;font-size:13px}.empty .button{margin-top:14px}.loading:before{content:"";display:inline-block;width:15px;height:15px;margin-right:8px;vertical-align:-2px;border:2px solid var(--line);border-top-color:var(--accent);border-radius:50%;animation:spin .8s linear infinite}.error{color:var(--danger)}.settings-box{overflow:hidden;border:1px solid var(--line);border-radius:12px;background:var(--surface)}.settings-row{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:14px 15px;border-top:1px solid var(--line)}.settings-row:first-child{border-top:0}.settings-main{min-width:0}.settings-title{font-weight:650}.settings-detail{margin-top:4px;color:var(--muted);font-size:12px;overflow-wrap:anywhere}.settings-row input{width:20px;height:20px;accent-color:var(--accent);flex:none}.toast{position:fixed;right:18px;bottom:18px;z-index:4;max-width:min(420px,calc(100vw - 36px));padding:12px 14px;border:1px solid var(--line);border-radius:8px;background:var(--surface);color:var(--ink);font-size:13px}.toast.error{border-color:var(--danger);color:var(--danger)}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@keyframes spin{to{transform:rotate(360deg)}}
