    @media(prefers-reduced-motion:reduce){*,*:before,*:after{scroll-behavior:auto!important;transition:none!important;animation:none!important}}
    .topbar-status{display:inline-flex;align-items:center;gap:7px;min-height:30px;padding:5px 10px;border:1px solid var(--line);border-radius:999px;background:var(--subtle);color:var(--muted);font-size:12px;font-weight:700;white-space:nowrap}.topbar-status:before{content:"";width:7px;height:7px;border-radius:50%;background:var(--muted)}.topbar-status.ready{color:var(--success);background:var(--success-soft);border-color:transparent}.topbar-status.ready:before{background:var(--success)}.topbar-status.warning{color:var(--accent);background:var(--accent-soft);border-color:transparent}.topbar-status.warning:before{background:var(--accent)}.topbar-status.error{color:var(--danger);background:var(--danger-soft);border-color:transparent}.topbar-status.error:before{background:var(--danger)}
    .metric-strip{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1px;margin-top:12px;border:1px solid var(--line);border-radius:12px;overflow:hidden;background:var(--line)}.metric{min-width:0;padding:13px 15px;background:var(--surface)}.metric-label{color:var(--muted);font-size:12px}.metric-value{margin-top:4px;font-size:18px;font-weight:750;font-variant-numeric:tabular-nums;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.metric-value.ok{color:var(--success)}.metric-value.warn{color:var(--danger)}
    .section-head{align-items:flex-end}.section-head .section-summary{max-width:620px}.toolbar{padding:10px;border:1px solid var(--line);border-radius:10px;background:var(--subtle)}.toolbar .search,.toolbar .filter{background:var(--surface)}.toolbar .button{white-space:nowrap}.sort{min-height:48px;padding:10px 28px 10px 11px;border:1px solid var(--line);border-radius:8px;background:var(--surface);color:var(--ink)}
    .list{box-shadow:0 1px 0 rgba(23,33,43,.04)}.module{min-height:78px}.module:hover{background:var(--subtle)}.module-main{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:8px 14px}.module-name,.module-meta{grid-column:1;min-width:0}.module-actions,.module-pending{grid-column:2;grid-row:1 / span 2}.module-actions{justify-content:flex-end}.module-actions .button{min-width:72px}.module-pending{align-self:center;color:var(--danger);font-size:12px;text-align:right}.settings-section-title{margin:22px 0 9px;font-size:13px;font-weight:750;color:var(--muted)}.settings-section-title:first-child{margin-top:0}.settings-box+.settings-section-title{margin-top:20px}.settings-hint{padding:12px 14px;border:1px solid var(--line);border-radius:10px;background:var(--accent-soft);color:var(--ink);font-size:13px}.settings-hint strong{color:var(--accent)}.settings-detail.status-ok{color:var(--success);font-weight:650}.settings-detail.status-warn{color:var(--danger);font-weight:650}
    .compact .module{min-height:64px}.compact .module-actions .button{min-height:40px}.reduce-motion *, .reduce-motion *:before, .reduce-motion *:after{animation-duration:.01ms!important;animation-iteration-count:1!important;scroll-behavior:auto!important;transition-duration:.01ms!important}\n    @media(max-width:700px){.topbar-status{display:none}.metric-strip{grid-template-columns:repeat(2,minmax(0,1fr))}.section-head{align-items:flex-start}.toolbar{padding:8px}.sort{flex:1}.module-main{grid-template-columns:minmax(0,1fr)}.module-actions,.module-pending{grid-column:1;grid-row:auto;justify-content:flex-start;text-align:left}.module-actions .button{min-width:96px}}
  </style>
</head>
<body>
  <main class="shell">
    <header class="topbar"><div class="brand"><div class="brand-mark" aria-hidden="true">A</div><div class="brand-copy"><div class="brand-title">ApkeSU 网页管理器</div><div class="brand-subtitle">本机控制台 · 仅回环访问</div></div></div><div class="topbar-actions"><span class="topbar-context">系统状态</span><span id="topbarStatus" class="topbar-status">读取中</span><button id="copyButton" hidden type="button">复制地址</button><button id="refreshButton" class="button secondary small" type="button">刷新</button></div></header>
    <nav class="tabs" role="tablist" aria-label="网页管理器页面"><button id="statusTab" class="tab active" role="tab" type="button" aria-selected="true" aria-controls="statusPage">主页</button><button id="superuserTab" class="tab" role="tab" type="button" aria-selected="false" aria-controls="superuserPage">超级用户 <span id="superuserTabCount" class="tab-count">-</span></button><button id="modulesTab" class="tab" role="tab" type="button" aria-selected="false" aria-controls="modulesPage">模块 <span id="modulesTabCount" class="tab-count">-</span></button><button id="settingsTab" class="tab" role="tab" type="button" aria-selected="false" aria-controls="settingsPage">设置</button></nav>
    <section id="statusPage" class="page" role="tabpanel" tabindex="0" aria-labelledby="statusHeading"><div class="home-head"><div><h1 id="statusHeading" class="section-title">状态概览</h1><p class="section-summary">快速确认 Root 服务和模块是否正常运行。</p></div></div><section class="home-status" aria-live="polite"><div class="home-status-copy"><div class="status-kicker">核心服务</div><div class="status-line"><span id="statusDot" class="status-dot off" aria-hidden="true"></span><span id="statusText">正在读取状态</span></div><div id="statusDetail" class="status-detail">正在检查本机网页服务……</div><div class="home-status-meta"><span id="securityChip" class="security-chip">仅本机访问</span><code id="localAddress" class="status-address">127.0.0.1:10240</code></div></div><div class="home-status-actions"><button id="copyStatusButton" class="button secondary small" type="button">复制访问地址</button><label class="check-label"><input id="autoRefresh" type="checkbox"> 每 10 秒刷新</label></div></section><div class="metric-strip" aria-label="关键指标"><div class="metric"><span class="metric-label">Root 服务</span><strong id="metricRoot" class="metric-value">读取中</strong></div><div class="metric"><span class="metric-label">已启用模块</span><strong id="metricEnabled" class="metric-value">-</strong></div><div class="metric"><span class="metric-label">已停用模块</span><strong id="metricDisabled" class="metric-value">-</strong></div><div class="metric"><span class="metric-label">待重启操作</span><strong id="metricPending" class="metric-value">-</strong></div></div><div class="home-grid"><section class="panel" aria-labelledby="runtimeHeading"><div class="panel-head"><h2 id="runtimeHeading" class="panel-title">运行概览</h2><span class="panel-count"><strong id="moduleCount">-</strong> 个模块</span></div><div id="runtime" class="runtime-grid" aria-busy="true"><div class="loading" style="grid-column:1/-1">正在读取运行状态</div></div></section><section class="panel" aria-labelledby="quickHeading"><div class="panel-head"><h2 id="quickHeading" class="panel-title">常用操作</h2><span class="panel-count">快速进入</span></div><div class="quick-list"><button class="quick-row" type="button" data-go="superuser"><span class="quick-row-mark" aria-hidden="true">SU</span><span class="quick-row-copy"><span class="quick-title">超级用户</span><span class="quick-detail">管理应用 Root 授权 · <span id="quickSuperuserCount">读取中</span></span></span><span class="quick-row-arrow" aria-hidden="true">›</span></button><button class="quick-row" type="button" data-go="modules"><span class="quick-row-mark" aria-hidden="true">M</span><span class="quick-row-copy"><span class="quick-title">模块管理</span><span class="quick-detail">启用、停用和卸载模块</span></span><span class="quick-row-arrow" aria-hidden="true">›</span></button><button class="quick-row" type="button" data-go="settings"><span class="quick-row-mark" aria-hidden="true">S</span><span class="quick-row-copy"><span class="quick-title">网页设置</span><span class="quick-detail">自动启动、刷新和安全状态</span></span><span class="quick-row-arrow" aria-hidden="true">›</span></button></div></section></div><details class="activity"><summary class="activity-summary"><span>最近操作</span><span class="small">查看日志</span></summary><div id="activityLog" class="activity-list" aria-live="polite"></div></details></section>
    <section id="superuserPage" class="page hidden" role="tabpanel" tabindex="0" aria-labelledby="superuserHeading"><div class="section-head"><div><h1 id="superuserHeading" class="section-title">超级用户</h1><p class="section-summary">直接使用内核应用配置管理 Root 授权。</p></div><span id="superuserResult" class="small result-count" aria-live="polite"></span></div><div class="superuser-stats" aria-live="polite"><div class="superuser-stat"><div id="superuserUidCount" class="superuser-stat-value">-</div><div class="superuser-stat-label">可管理 UID</div></div><div class="superuser-stat"><div id="superuserAppCount" class="superuser-stat-value">-</div><div class="superuser-stat-label">应用</div></div><div class="superuser-stat"><div id="superuserAuthorizedCount" class="superuser-stat-value">-</div><div class="superuser-stat-label">已授权 UID</div></div><div class="superuser-stat"><div id="superuserSharedCount" class="superuser-stat-value">-</div><div class="superuser-stat-label">共享 UID</div></div></div><div id="superuserError" class="notice error hidden" role="alert"><span id="superuserErrorText"></span><button class="button secondary small" type="button" data-retry="superuser">重试</button></div><div class="toolbar"><label class="sr-only" for="superuserSearch">搜索应用</label><input id="superuserSearch" class="search" type="search" placeholder="搜索应用名称、包名或 UID" autocomplete="off"><label class="sr-only" for="superuserFilter">筛选授权状态</label><select id="superuserFilter" class="filter"><option value="all">全部状态</option><option value="granted">已授权</option><option value="not-granted">未授权</option></select><label class="sr-only" for="appSort">应用排序</label><select id="appSort" class="sort"><option value="label">按名称排序</option><option value="uid">按 UID 排序</option><option value="status">按授权状态排序</option></select><button id="superuserRefreshButton" class="button secondary small" type="button">刷新授权</button></div><div id="superusers" class="list" aria-live="polite" aria-busy="true"><div class="loading">正在读取授权列表</div></div></section>
    <section id="modulesPage" class="page hidden" role="tabpanel" tabindex="0" aria-labelledby="modulesHeading"><div class="section-head"><div><h1 id="modulesHeading" class="section-title">模块管理</h1><p class="section-summary">可以启用、停用或卸载模块；卸载通常需要重启后完成。</p></div><span id="moduleResult" class="small result-count" aria-live="polite"></span></div><div class="metric-strip" aria-label="模块状态"><div class="metric"><span class="metric-label">全部</span><strong id="moduleTotal" class="metric-value">-</strong></div><div class="metric"><span class="metric-label">已启用</span><strong id="moduleEnabled" class="metric-value">-</strong></div><div class="metric"><span class="metric-label">已停用</span><strong id="moduleDisabled" class="metric-value">-</strong></div><div class="metric"><span class="metric-label">待重启</span><strong id="modulePending" class="metric-value">-</strong></div></div><div id="moduleError" class="notice error hidden" role="alert"><span id="moduleErrorText"></span><button class="button secondary small" type="button" data-retry="modules">重试</button></div><div class="toolbar"><label class="sr-only" for="moduleSearch">搜索模块</label><input id="moduleSearch" class="search" type="search" placeholder="搜索模块名称或 ID" autocomplete="off"><label class="sr-only" for="moduleFilter">筛选模块</label><select id="moduleFilter" class="filter"><option value="all">全部模块</option><option value="enabled">已启用</option><option value="disabled">已停用</option><option value="pending">待重启移除</option></select><label class="sr-only" for="moduleSort">模块排序</label><select id="moduleSort" class="sort"><option value="name">按名称排序</option><option value="status">按状态排序</option><option value="version">按版本排序</option></select><button id="moduleRefreshButton" class="button secondary small" type="button">刷新模块</button></div><div id="modules" class="list" aria-live="polite" aria-busy="true"><div class="loading">正在读取模块</div></div></section>
    <section id="settingsPage" class="page hidden" role="tabpanel" tabindex="0" aria-labelledby="settingsHeading"><div class="section-head"><div><h1 id="settingsHeading" class="section-title">设置</h1><p class="section-summary">网页管理器的运行和安全选项。</p></div></div><div id="settingsError" class="notice error hidden" role="alert"><span id="settingsErrorText"></span><button class="button secondary small" type="button" data-retry="settings">重试</button></div><div class="settings-section-title">服务</div><div class="settings-box"><label class="settings-row"><div class="settings-main"><div class="settings-title">开机自动启动</div><div class="settings-detail">下次开机后自动启动 127.0.0.1:10240 服务，当前服务不会被停止。</div></div><input id="autoStart" type="checkbox"></label><div class="settings-row"><div class="settings-main"><div class="settings-title">服务状态</div><div id="settingsServiceStatus" class="settings-detail">读取中</div></div></div><div class="settings-row"><div class="settings-main"><div class="settings-title">监听地址</div><div id="settingsAddress" class="settings-detail">127.0.0.1:10240</div></div></div><div class="settings-row"><div class="settings-main"><div class="settings-title">运行时长</div><div id="settingsUptime" class="settings-detail">读取中</div></div></div></div><div class="settings-section-title">访问安全</div><div class="settings-box"><div class="settings-row"><div class="settings-main"><div class="settings-title">安全策略</div><div class="settings-detail">仅允许本机访问，页面操作需要随机访问令牌。</div></div></div><div class="settings-hint"><strong>本机保护</strong><br>网页管理器只监听回环地址，不会直接暴露到局域网。</div></div><div class="settings-section-title">刷新策略</div><div class="settings-box"><label class="settings-row"><div class="settings-main"><div class="settings-title">自动刷新</div><div class="settings-detail">每 10 秒刷新状态、模块和超级用户数据。</div></div><input id="settingsAutoRefresh" type="checkbox"></label></div><div class="settings-section-title">显示</div><div class="settings-box"><label class="settings-row"><div class="settings-main"><div class="settings-title">紧凑列表</div><div class="settings-detail">减少模块和授权列表的行高，适合小屏幕。</div></div><input id="compactMode" type="checkbox"></label><label class="settings-row"><div class="settings-main"><div class="settings-title">减少动画</div><div class="settings-detail">关闭页面过渡和加载动画，降低动态效果。</div></div><input id="reduceMotion" type="checkbox"></label></div></section>
  </main>
  <div id="toast" class="toast hidden" role="status"></div>
  <script>
    const tokenStorageKey='apkesu_web_token';
    const queryToken=new URLSearchParams(location.search).get('token')||'';
    let token=queryToken;
    try{
      if(queryToken)sessionStorage.setItem(tokenStorageKey,queryToken);
      else token=sessionStorage.getItem(tokenStorageKey)||'';
      if(queryToken)history.replaceState(null,document.title,location.pathname+location.hash);
    }catch(_){ }
    const authHeaders={'Authorization':'Bearer '+token};
    const state={modules:[],apps:[],query:'',filter:'all',appQuery:'',appFilter:'all',appStats:{uidCount:0,totalApps:0,authorizedCount:0,sharedUidCount:0},moduleSort:'name',appSort:'label',busy:new Set(),modulesLoaded:false,appsLoaded:false,modulesStale:false,appsStale:false,refreshing:false,autoRefresh:false,timer:null,activity:[],preferences:{compact:storedFlag('web_manager_compact'),reduceMotion:storedFlag('web_manager_reduceMotion')}};document.documentElement.classList.toggle('compact',state.preferences.compact);document.documentElement.classList.toggle('reduce-motion',state.preferences.reduceMotion);
    const pageIds={home:'statusPage',superuser:'superuserPage',modules:'modulesPage',settings:'settingsPage'};const tabIds={home:'statusTab',superuser:'superuserTab',modules:'modulesTab',settings:'settingsTab'};
    const byId=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function storedFlag(key){try{return localStorage.getItem(key)==='1'}catch(_){return false}}function setLocalPreference(key,enabled){state.preferences[key]=enabled;try{localStorage.setItem('web_manager_'+key,enabled?'1':'0')}catch(_){}const className=key==='compact'?'compact':'reduce-motion';document.documentElement.classList.toggle(className,enabled);byId(key==='compact'?'compactMode':'reduceMotion').checked=enabled;notify(key==='compact'?(enabled?'已开启紧凑列表':'已关闭紧凑列表'):(enabled?'已减少动画':'已恢复动画'))}let toastTimer;
    function timestamp(){return new Intl.DateTimeFormat('zh-CN',{hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date())}function formatUptime(seconds){const value=Math.max(0,Math.floor(Number(seconds)||0));const days=Math.floor(value/86400);const hours=Math.floor(value%86400/3600);const minutes=Math.floor(value%3600/60);const secs=value%60;return (days?days+'天 ':'')+(hours?hours+'小时 ':'')+(minutes?minutes+'分 ':'')+secs+'秒'}function address(){return location.origin+'/?token='+encodeURIComponent(token)}
    async function api(path,options={}){const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),15000);try{const request={...options,headers:Object.assign({},authHeaders,options.headers||{}),signal:controller.signal};const response=await fetch(path,request);const data=await response.json().catch(()=>({error:'服务器返回了无效数据'}));if(!response.ok){const error=new Error(data.error||response.statusText||'请求失败');error.code=data.errorCode||('http_'+response.status);error.detail=data.detail||'';error.status=response.status;throw error}return data}catch(error){if(error.name==='AbortError'){const timeoutError=new Error('请求超时');timeoutError.code='request_timeout';throw timeoutError}throw error}finally{clearTimeout(timeout)}}
    function notify(message,error=false){const toast=byId('toast');toast.textContent=message;toast.className='toast'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.className='toast hidden',3600)}function recordActivity(message,error=false){state.activity.unshift({time:timestamp(),message,error});state.activity=state.activity.slice(0,6);byId('activityLog').innerHTML=state.activity.map(item=>'<div class="activity-item'+(item.error?' error':'')+'"><span class="activity-time">'+esc(item.time)+'</span><span>'+esc(item.message)+'</span></div>').join('')}
    async function copyAddress(){try{await navigator.clipboard.writeText(address());notify('本机访问地址已复制');recordActivity('已复制本机访问地址')}catch(error){notify('浏览器拒绝复制，请手动复制地址',true);recordActivity('复制地址失败',true)}}function setTab(page){Object.keys(pageIds).forEach(key=>{const selected=key===page;byId(pageIds[key]).classList.toggle('hidden',!selected);byId(tabIds[key]).classList.toggle('active',selected);byId(tabIds[key]).setAttribute('aria-selected',String(selected))});}
    function setLoading(id,loading){byId(id).setAttribute('aria-busy',String(loading))}function updateModuleCounts(){if(!state.modulesLoaded)return;const total=state.modules.length;const visible=filteredModules().length;const enabled=state.modules.filter(module=>!module.remove&&module.enabled).length;const pending=state.modules.filter(module=>module.remove).length;const disabled=Math.max(0,total-enabled-pending);byId('moduleCount').textContent=String(total);byId('modulesTabCount').textContent=String(total);byId('moduleTotal').textContent=String(total);byId('moduleEnabled').textContent=String(enabled);byId('moduleDisabled').textContent=String(disabled);byId('modulePending').textContent=String(pending);byId('moduleResult').textContent=(state.modulesStale?'数据可能已过期 · ':'')+'显示 '+visible+' / '+total+' 个模块';}
    function showStatusError(error){const message=error.message||'无法读取运行状态';byId('topbarStatus').textContent='服务异常';byId('topbarStatus').className='topbar-status error';byId('metricRoot').textContent='不可用';byId('metricRoot').className='metric-value warn';['metricEnabled','metricDisabled','metricPending','moduleCount'].forEach(id=>byId(id).textContent='—');byId('statusDot').className='status-dot off';byId('statusText').textContent='服务状态不可用';byId('statusText').className='error';byId('statusDetail').textContent=message;byId('securityChip').className='security-chip warning';byId('securityChip').textContent='请检查连接';byId('quickSuperuserCount').textContent=state.appsLoaded?String(state.appStats.totalApps)+' 个应用':'暂不可用';byId('runtime').innerHTML='<div class="empty error" style="grid-column:1/-1"><div class="empty-title">无法读取运行状态</div><div class="empty-detail">'+esc(message)+'</div><button class="button secondary small" type="button" data-retry="status">重试</button></div>';setLoading('runtime',false);recordActivity('读取运行状态失败：'+message,true)}
    async function loadStatus(){try{const data=await api('/api/status');const serverRunning=data.serverRunning!==false;const rootReady=Boolean(data.root);const moduleQueryOk=data.moduleQueryOk!==false;const degraded=serverRunning&&rootReady&&!moduleQueryOk;const ready=serverRunning&&rootReady;const loopback=Boolean(data.loopback);const port=String(data.port??'10240');const stamp=timestamp();const enabledCount=Number(data.moduleEnabledCount??0);const pendingCount=Number(data.modulePendingCount??0);const totalCount=Number(data.moduleCount??0);const disabledCount=Math.max(0,totalCount-enabledCount-pendingCount);const statusLabel=!serverRunning?'服务异常':!rootReady?'Root 不可用':degraded?'部分可用':'运行正常';byId('topbarStatus').textContent=statusLabel;byId('topbarStatus').className='topbar-status'+(ready?(degraded?' warning':' ready'):' error');byId('metricRoot').textContent=ready?'已就绪':'不可用';byId('metricRoot').className='metric-value'+(ready?'':' warn');byId('metricEnabled').textContent=moduleQueryOk?String(enabledCount):'暂不可用';byId('metricDisabled').textContent=moduleQueryOk?String(disabledCount):'暂不可用';byId('metricPending').textContent=moduleQueryOk?String(pendingCount):'暂不可用';byId('statusDot').className='status-dot'+(ready?(degraded?' warning':''):' off');byId('statusText').textContent=!serverRunning?'网页服务未运行':!rootReady?'Root 服务不可用':degraded?'Root 服务已就绪，模块状态暂不可用':'Root 服务已就绪';byId('statusText').className=ready?'':'error';byId('statusDetail').textContent='127.0.0.1:'+port+' · '+(loopback?'仅本机访问':'网络监听')+' · '+(moduleQueryOk?'模块状态已同步':'模块状态暂不可用')+' · 更新于 '+stamp;byId('localAddress').textContent='127.0.0.1:'+port;byId('securityChip').className='security-chip'+(loopback?'':' warning');byId('securityChip').textContent=loopback?'仅本机访问':'存在网络暴露';if(!state.modulesLoaded)byId('moduleCount').textContent=moduleQueryOk?String(totalCount):'暂不可用';byId('quickSuperuserCount').textContent=state.appsLoaded?String(state.appStats.totalApps)+' 个应用':'读取中';const runtimeItems=[['接口版本',data.apiVersion],['监听地址','127.0.0.1:'+port],['服务状态',serverRunning?'运行中':'未运行'],['Root 权限',rootReady?'可用':'不可用'],['模块状态',moduleQueryOk?'可用':'暂不可用'],['模块总数',moduleQueryOk?totalCount:'暂不可用'],['已启用',moduleQueryOk?enabledCount:'暂不可用'],['待重启移除',moduleQueryOk?pendingCount:'暂不可用']];byId('runtime').innerHTML=runtimeItems.map(item=>'<div class="runtime-item"><div class="runtime-label">'+esc(item[0])+'</div><div class="runtime-value'+((item[0]==='Root 权限'&&!rootReady)||(item[0]==='模块状态'&&!moduleQueryOk)?' error':'')+'">'+esc(item[1])+'</div></div>').join('');setLoading('runtime',false);return true}catch(error){showStatusError(error);return false}}
    function filteredModules(){const query=state.query.trim().toLowerCase();const modules=state.modules.filter(module=>{const name=String(module.name??'');const id=String(module.id??'');const matchesFilter=state.filter==='all'||(state.filter==='enabled'&&module.enabled)||(state.filter==='disabled'&&!module.enabled)||(state.filter==='pending'&&module.remove);const matchesQuery=!query||name.toLowerCase().includes(query)||id.toLowerCase().includes(query);return matchesFilter&&matchesQuery});const statusRank=module=>module.remove?0:module.enabled?1:2;return modules.sort((a,b)=>{if(state.moduleSort==='status')return statusRank(a)-statusRank(b)||String(a.name??a.id??'').localeCompare(String(b.name??b.id??''),'zh-CN');if(state.moduleSort==='version')return String(b.version??'').localeCompare(String(a.version??''),undefined,{numeric:true,sensitivity:'base'})||String(a.name??a.id??'').localeCompare(String(b.name??b.id??''),'zh-CN');return String(a.name??a.id??'').localeCompare(String(b.name??b.id??''),'zh-CN')})}
    function renderModules(){const box=byId('modules');const modules=filteredModules();updateModuleCounts();if(!state.modules.length){box.innerHTML='<div class="empty"><div class="empty-title">没有已安装模块</div><div class="empty-detail">本机已安装的模块会显示在这里。</div></div>';return}if(!modules.length){box.innerHTML='<div class="empty"><div class="empty-title">没有匹配的模块</div><div class="empty-detail">请更换搜索关键词或筛选条件。</div></div>';return}box.innerHTML=modules.map(module=>{const id=String(module.id??'');const name=String(module.name||id||'?');const encoded=encodeURIComponent(id);const busy=state.busy.has(id);const pending=Boolean(module.remove);const status=pending?'<span class="chip pending">待重启移除</span>':module.enabled?'<span class="chip">已启用</span>':'<span class="chip off">已停用</span>';const webUiChip=module.webui?'<span class="chip">WebUI</span>':'';const webUiButton=module.webui&&!pending?'<button class="button secondary small" type="button" data-module="'+esc(encoded)+'" data-action="webui"'+(!module.enabled||busy?' disabled':'')+'>打开 WebUI</button>':'';const action=module.enabled?'停用':'启用';const initial=esc((name.trim()[0]||'?').toUpperCase());const actions=pending?'<div class="module-pending">重启后完成移除。</div>':'<div class="module-actions">'+webUiButton+'<button class="button secondary small" type="button" data-module="'+esc(encoded)+'" data-action="'+(module.enabled?'disable':'enable')+'"'+(busy?' disabled':'')+'>'+ (busy?'处理中……':action)+'</button><button class="button danger small" type="button" data-module="'+esc(encoded)+'" data-action="uninstall"'+(busy?' disabled':'')+'>卸载</button></div>';return '<article class="module"><div class="module-icon" aria-hidden="true">'+initial+'</div><div class="module-main"><div class="module-name">'+esc(name)+'</div><div class="module-meta"><span class="module-id">'+esc(id)+'</span><span aria-hidden="true">·</span><span>'+esc(String(module.version??'未知版本'))+'</span>'+status+webUiChip+'</div>'+actions+'</div></article>'}).join('')}
    function showModuleError(error){const notice=byId('moduleError');const message=error.message||'无法读取模块';const code=error.code?' ['+error.code+']':'';state.modulesStale=state.modulesLoaded;byId('moduleErrorText').textContent=message+code+(state.modulesLoaded?' · 当前显示上次成功读取的数据':'');notice.classList.remove('hidden');recordActivity('读取模块失败：'+message,true)}async function loadModules(){setLoading('modules',true);const box=byId('modules');if(!state.modulesLoaded)box.innerHTML='<div class="loading">正在读取模块</div>';else box.classList.add('is-loading');try{const data=await api('/api/modules');if(data.error)throw new Error(data.error);state.modules=Array.isArray(data.modules)?data.modules:[];state.modulesLoaded=true;state.modulesStale=false;byId('moduleError').classList.add('hidden');renderModules();return true}catch(error){showModuleError(error);if(state.modulesLoaded)renderModules();else box.innerHTML='<div class="empty error"><div class="empty-title">无法读取模块</div><div class="empty-detail">'+esc(error.message||'未知错误')+'</div><button class="button secondary small" type="button" data-retry="modules">重试</button></div>';return false}finally{box.classList.remove('is-loading');setLoading('modules',false)}}
    function filteredApps(){const query=state.appQuery.trim().toLowerCase();const apps=state.apps.filter(app=>{const matchesQuery=!query||String(app.label??'').toLowerCase().includes(query)||String(app.packageName??'').toLowerCase().includes(query)||String(app.uid??'').includes(query);const matchesFilter=state.appFilter==='all'||(state.appFilter==='granted'&&app.allowSu)||(state.appFilter==='not-granted'&&!app.allowSu);return matchesQuery&&matchesFilter});return apps.sort((a,b)=>{if(state.appSort==='uid')return Number(a.uid)-Number(b.uid);if(state.appSort==='status')return Number(Boolean(b.allowSu))-Number(Boolean(a.allowSu))||String(a.label??a.packageName??'').localeCompare(String(b.label??b.packageName??''),'zh-CN');return String(a.label??a.packageName??'').localeCompare(String(b.label??b.packageName??''),'zh-CN')})}function renderSuperusers(){const box=byId('superusers');const apps=filteredApps();byId('superuserResult').textContent=(state.appsStale?'数据可能已过期 · ':'')+'显示 '+apps.length+' / '+state.apps.length+' 个 UID';byId('superuserTabCount').textContent=String(state.apps.length);byId('superuserUidCount').textContent=String(state.appStats.uidCount);byId('superuserAppCount').textContent=String(state.appStats.totalApps);byId('superuserAuthorizedCount').textContent=String(state.appStats.authorizedCount);byId('superuserSharedCount').textContent=String(state.appStats.sharedUidCount);if(!state.apps.length){box.innerHTML='<div class="empty"><div class="empty-title">没有可管理的应用</div><div class="empty-detail">请确认 Root 服务和超级用户列表可用。</div></div>';return}if(!apps.length){box.innerHTML='<div class="empty"><div class="empty-title">没有匹配的应用</div><div class="empty-detail">请更换搜索关键词。</div></div>';return}box.innerHTML=apps.map(app=>{const uid=String(app.uid);const busy=state.busy.has('su:'+uid);const appCount=Number(app.appCount??1);const manageable=app.manageable!==false;const allowed=Boolean(app.allowSu);const status=allowed?'<span class="chip">已允许 Root</span>':'<span class="chip off">未允许 Root</span>';const action=allowed?'禁止 Root':'允许 Root';const initial=esc((String(app.label||app.packageName||'?').trim()[0]||'?').toUpperCase());return '<article class="module"><div class="module-icon" aria-hidden="true">'+initial+'</div><div class="module-main"><div class="module-name">'+esc(app.label||app.packageName)+'</div><div class="module-meta"><span class="module-id">'+esc(app.packageName)+'</span><span aria-hidden="true">·</span><span>UID '+esc(uid)+'</span><span>'+ (appCount>1?esc(String(appCount))+' 个应用':'单应用')+'</span>'+status+'</div><div class="module-actions"><button class="button '+(allowed?'danger':'secondary')+' small" type="button" data-app-uid="'+esc(uid)+'" data-action="'+(allowed?'revoke':'grant')+'"'+(busy||!manageable?' disabled':'')+'>'+ (busy?'处理中……':action)+'</button></div></div></article>'}).join('') }
    async function loadSuperusers(){setLoading('superusers',true);const box=byId('superusers');if(state.appsLoaded)box.classList.add('is-loading');else box.innerHTML='<div class="loading">正在读取授权列表</div>';try{const data=await api('/api/superuser');if(data.error)throw new Error(data.error);state.apps=Array.isArray(data.apps)?data.apps:[];state.appStats={uidCount:Number(data.uidCount??state.apps.length),totalApps:Number(data.totalApps??state.apps.length),authorizedCount:Number(data.authorizedCount??0),sharedUidCount:Number(data.sharedUidCount??0)};state.appsLoaded=true;state.appsStale=false;byId('superuserError').classList.add('hidden');renderSuperusers();return true}catch(error){const message=error.message||'无法读取授权列表';const code=error.code?' ['+error.code+']':'';state.appsStale=state.appsLoaded;byId('superuserErrorText').textContent=message+code+(state.appsLoaded?' · 当前显示上次成功读取的数据':'');byId('superuserError').classList.remove('hidden');if(state.appsLoaded)renderSuperusers();else box.innerHTML='<div class="empty error"><div class="empty-title">无法读取授权列表</div><div class="empty-detail">'+esc(message)+'</div><button class="button secondary small" type="button" data-retry="superuser">重试</button></div>';recordActivity('读取超级用户失败：'+message,true);return false}finally{box.classList.remove('is-loading');setLoading('superusers',false)}}
    async function changeSuperuser(uid,action){const key='su:'+uid;if(state.busy.has(key))return;if(!window.confirm(action==='grant'?'允许该应用获得 Root 权限？':'撤销该应用的 Root 权限？'))return;state.busy.add(key);renderSuperusers();try{await api('/api/superuser/'+encodeURIComponent(uid)+'/'+action,{method:'POST'});const message=action==='grant'?'已允许应用使用 Root':'已撤销应用 Root 权限';notify(message);recordActivity(message);await loadSuperusers();await loadStatus()}catch(error){notify(error.message,true);recordActivity('超级用户操作失败：'+error.message,true)}finally{state.busy.delete(key);renderSuperusers()}}
    async function loadSettings(){try{const data=await api('/api/settings');const running=data.running!==false;const port=String(data.port??'10240');byId('autoStart').checked=Boolean(data.autoStart);byId('settingsAutoRefresh').checked=state.autoRefresh;byId('compactMode').checked=state.preferences.compact;byId('reduceMotion').checked=state.preferences.reduceMotion;byId('settingsServiceStatus').textContent=running?'服务运行中':'服务未运行';byId('settingsServiceStatus').className='settings-detail '+(running?'status-ok':'status-warn');byId('settingsAddress').textContent='127.0.0.1:'+port+' · '+(data.loopback?'仅本机访问':'网络监听');const uptime=Number(data.uptimeSeconds??0);byId('settingsUptime').textContent=running?formatUptime(uptime):'暂不可用';byId('settingsError').classList.add('hidden');return true}catch(error){byId('settingsServiceStatus').textContent='暂不可用';byId('settingsServiceStatus').className='settings-detail status-warn';byId('settingsUptime').textContent='暂不可用';byId('settingsErrorText').textContent=error.message||'无法读取网页设置';byId('settingsError').classList.remove('hidden');recordActivity('读取网页设置失败：'+(error.message||'未知错误'),true);return false}}
    async function changeAutoStart(){const checkbox=byId('autoStart');const enabled=checkbox.checked;checkbox.disabled=true;try{await api('/api/settings/auto-start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled})});notify(enabled?'已开启开机自动启动':'已关闭开机自动启动');recordActivity(enabled?'已开启开机自动启动':'已关闭开机自动启动')}catch(error){checkbox.checked=!enabled;notify(error.message,true);recordActivity('保存网页设置失败：'+error.message,true)}finally{checkbox.disabled=false}}
    async function changeModule(id,action){if(action==='webui'){location.assign('/webui/'+encodeURIComponent(id)+'/');return}if(state.busy.has(id))return;if(action==='uninstall'&&!window.confirm('确定要卸载这个模块吗？卸载通常需要重启后完成。'))return;state.busy.add(id);renderModules();try{await api('/api/modules/'+encodeURIComponent(id)+'/'+action,{method:'POST'});const message=action==='uninstall'?'已安排卸载，重启后完成':(action==='enable'?'模块已启用':'模块已停用');notify(message);recordActivity(message);await loadModules();await loadStatus()}catch(error){notify(error.message,true);recordActivity('模块操作失败：'+error.message,true)}finally{state.busy.delete(id);renderModules()}}
    async function loadAll(){if(state.refreshing)return;state.refreshing=true;byId('refreshButton').disabled=true;try{await Promise.all([loadStatus(),loadModules(),loadSuperusers(),loadSettings()])}finally{byId('refreshButton').disabled=false;state.refreshing=false}}function setAutoRefresh(enabled){state.autoRefresh=enabled;byId('autoRefresh').checked=enabled;byId('settingsAutoRefresh').checked=enabled;clearInterval(state.timer);state.timer=null;if(enabled){state.timer=setInterval(()=>{if(!state.refreshing)loadAll()},10000);notify('已开启每 10 秒自动刷新');recordActivity('已开启自动刷新')}else{notify('已关闭自动刷新');recordActivity('已关闭自动刷新')}}
    const tabNames=['home','superuser','modules','settings'];tabNames.forEach((name,index)=>{const tab=byId(tabIds[name]);tab.addEventListener('click',()=>setTab(name));tab.addEventListener('keydown',event=>{if(event.key!=='ArrowLeft'&&event.key!=='ArrowRight')return;event.preventDefault();const next=(index+(event.key==='ArrowRight'?1:-1)+tabNames.length)%tabNames.length;setTab(tabNames[next]);byId(tabIds[tabNames[next]]).focus()})});document.querySelectorAll('[data-go]').forEach(button=>button.addEventListener('click',()=>setTab(button.dataset.go)));byId('refreshButton').addEventListener('click',loadAll);byId('moduleRefreshButton').addEventListener('click',loadModules);byId('superuserRefreshButton').addEventListener('click',loadSuperusers);byId('copyButton').addEventListener('click',copyAddress);byId('copyStatusButton').addEventListener('click',copyAddress);byId('autoRefresh').addEventListener('change',event=>setAutoRefresh(event.target.checked));byId('settingsAutoRefresh').addEventListener('change',event=>setAutoRefresh(event.target.checked));byId('compactMode').addEventListener('change',event=>setLocalPreference('compact',event.target.checked));byId('reduceMotion').addEventListener('change',event=>setLocalPreference('reduceMotion',event.target.checked));byId('autoStart').addEventListener('change',changeAutoStart);byId('moduleSearch').addEventListener('input',event=>{state.query=event.target.value;renderModules()});byId('moduleFilter').addEventListener('change',event=>{state.filter=event.target.value;renderModules()});byId('moduleSort').addEventListener('change',event=>{state.moduleSort=event.target.value;renderModules()});byId('superuserSearch').addEventListener('input',event=>{state.appQuery=event.target.value;renderSuperusers()});byId('superuserFilter').addEventListener('change',event=>{state.appFilter=event.target.value;renderSuperusers()});byId('appSort').addEventListener('change',event=>{state.appSort=event.target.value;renderSuperusers()});byId('modules').addEventListener('click',event=>{const button=event.target.closest('button[data-module]');if(!button)return;changeModule(decodeURIComponent(button.dataset.module),button.dataset.action)});byId('superusers').addEventListener('click',event=>{const button=event.target.closest('button[data-app-uid]');if(!button)return;changeSuperuser(button.dataset.appUid,button.dataset.action)});document.addEventListener('click',event=>{const button=event.target.closest('[data-retry]');if(!button)return;button.disabled=true;const request=button.dataset.retry==='status'?loadStatus():button.dataset.retry==='superuser'?loadSuperusers():button.dataset.retry==='settings'?loadSettings():loadModules();request.finally(()=>{if(button.isConnected)button.disabled=false})});recordActivity('网页管理器已加载');loadAll();
  </script>
